const b = ($('Webhook').first().json.body) || {};
const stored = $input.first() ? ($input.first().json || {}) : {};
const fromBody = (typeof b.pdfText === 'string') ? b.pdfText.trim() : '';
const fromStore = (typeof stored.pdf_text === 'string') ? stored.pdf_text.trim() : '';
const pdfText = fromBody || fromStore;
const request = String(b.question || b.prompt || b.message || b.request || '').trim();
const lower = request.toLowerCase();
const pick = function () { for (const v of arguments) { if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } return ''; };

// Subject
let subject = pick(b.subject, b.subjects);
if (!subject) {
  const m1 = request.match(/\d+\s*-?\s*(?:day|week|month)s?\s+([A-Za-z0-9+#.\- ]+?)\s+(?:study|learning)\s+(?:plan|schedule)/i);
  const m2 = request.match(/(?:study|learning)\s+(?:plan|schedule)\s+(?:for|on)\s+(?:learning\s+)?([^.,;\n]+?)(?:\s+(?:for|in|with|focus|at|i\s+can)\b|[.,;\n]|$)/i);
  const m3 = request.match(/(?:learn|study)\s+([A-Za-z0-9+#.\- ]+?)(?:\s+(?:in|for|with|focus|at)\b|[.,;\n]|$)/i);
  const m = m1 || m2 || m3;
  if (m && m[1]) subject = m[1].replace(/^(a|an|the)\s+/i, '').replace(/\b(beginner|intermediate|advanced)\b/ig, '').trim();
}
if (!subject || /^(a|an|the|my|me|plan|schedule|study|studying|learning|something|it|this|that)$/i.test(subject.trim())) subject = 'Python';

// Duration in days
let days = parseInt(pick(b.days, b.duration), 10);
if (!days) {
  const d = request.match(/(\d+)\s*-?\s*(day|week|month)s?/i);
  if (d) {
    const n = parseInt(d[1], 10);
    const u = d[2].toLowerCase();
    days = u === 'week' ? n * 7 : u === 'month' ? n * 30 : n;
  }
}
if (!days || days < 1) days = 7;
if (days > 60) days = 60;

// Study time per day, in minutes
let minutes = 0;
const hp = pick(b.availableHours, b.studyHours, b.hoursPerDay);
if (hp && parseFloat(hp) > 0) minutes = Math.round(parseFloat(hp) * 60);
if (!minutes) {
  const h = lower.match(/(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h)\b/);
  const mm = lower.match(/(\d+)\s*(?:minutes?|mins?)\b/);
  if (h) minutes = Math.round(parseFloat(h[1]) * 60);
  else if (mm) minutes = parseInt(mm[1], 10);
  else if (/an hour|one hour/.test(lower)) minutes = 60;
}
if (!minutes || minutes < 10) minutes = 60;
const timeText = minutes % 60 === 0 ? (minutes / 60) + ' hour' + (minutes === 60 ? '' : 's') : minutes + ' minutes';

// Level
let level = pick(b.level, b.difficulty);
if (!level) {
  const l = lower.match(/\b(beginner|intermediate|advanced)\b/);
  level = l ? l[1] : 'Beginner';
}
level = level.charAt(0).toUpperCase() + level.slice(1).toLowerCase();

const focus = pick(b.difficultTopics, b.focus);

const mentionsPdf = /\b(pdf|uploaded|upload|document|file)\b/i.test(request) || fromBody !== '';
if (mentionsPdf) {
  if (!pdfText) {
    return [{ json: { valid: false, error: 'No PDF text is available. Please upload a PDF first, then ask for the study plan again.', prompt: '' } }];
  }
  const pdfPrompt = 'Use ONLY the PDF text below. Do not use outside knowledge.\n\nPDF TEXT:\n' + pdfText +
    '\n\nREQUIREMENTS:\n- Duration: ' + days + ' days (write exactly ' + days + ' day sections, Day 1 to Day ' + days + ')\n' +
    '- Study time: ' + timeText + ' per day (' + minutes + ' minutes)\n' +
    (focus ? '- Focus topics: ' + focus + '\n' : '') +
    '\nUSER REQUEST:\n' + (request || 'Create a study plan from the uploaded PDF.');
  return [{ json: { valid: true, usesPdf: true, error: '', prompt: pdfPrompt, days: days, minutesPerDay: minutes } }];
}


const prompt = 'Create the complete study plan now using these final requirements:\n' +
  '- Subject: ' + subject + '\n' +
  '- Duration: ' + days + ' days (write exactly ' + days + ' day sections, Day 1 to Day ' + days + ')\n' +
  '- Study time: ' + timeText + ' per day (' + minutes + ' minutes)\n' +
  '- Level: ' + level + '\n' +
  (focus ? '- Focus topics: ' + focus + '\n' : '') +
  (request ? '\nOriginal user request (honour any extra focus areas or preferences in it):\n' + request : '');

return [{ json: { valid: true, usesPdf: false, error: '', prompt: prompt, subject: subject, days: days, minutesPerDay: minutes, level: level } }];
